INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'European Bartender School', NULL, 'https://www.barschool.net', NULL, NULL, 'Міжнародна школа барменів і барист з курсами в 19 школах світу й допомогою з працевлаштуванням.', 'An international bartender and barista school with courses in 19 schools worldwide and job support.', 'European Bartender School з 1999 року проводить курси для барменів і барист, видає сертифікат EBS і допомагає з пошуком роботи через EBS MatchStaff.', 'European Bartender School has run bartender and barista courses since 1999, issues the EBS certificate and helps with job searching through EBS MatchStaff.', 'Курси барменів і барист
Сертифікат EBS
Допомога з роботою', 'Bartender and barista courses
EBS certificate
Job support', 'Майбутні бармени й баристи.', 'Aspiring bartenders and baristas.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-10 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'barschool.net' OR LOWER(`name`) = 'european bartender school') ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, @cat FROM DUAL WHERE @pid IS NOT NULL AND @cat IS NOT NULL;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, @sub FROM DUAL WHERE @pid IS NOT NULL AND @sub IS NOT NULL;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'An international bartender and barista school with courses in 19 schools worldwide and job support.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'European Bartender School has run bartender and barista courses since 1999, issues the EBS certificate and helps with job searching through EBS MatchStaff.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Bartender and barista courses
EBS certificate
Job support', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'Aspiring bartenders and baristas.', 'manual' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Ціна: див. сайт', 'Price: see website', NULL, 'one_time', 'Актуальні ціни й умови — на офіційному сайті.', 'Current prices and terms are on the official website.' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Ціна: див. сайт' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Price: see website', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', 'Current prices and terms are on the official website.', 'manual' FROM DUAL WHERE @plan IS NOT NULL;

